"""
Testy dla S01E02 — findhim.

Wyłącznie unit testy na czystych funkcjach (offline, bez sieci/huba/Nominatim) —
zadanie jest deterministyczne, więc nie ma tu warstwy LLM do zamockowania.
"""

from __future__ import annotations

import json

import pytest

from tasks.s01e02_findhim.solution import (
    Match,
    PowerPlant,
    find_closest_match,
    format_answer,
    haversine_km,
    parse_power_plants,
)

SAMPLE_LOCATIONS_JSON = json.dumps(
    {
        "power_plants": {
            "Zabrze": {"is_active": True, "power": "35 MW", "code": "PWR3847PL"},
            "Chelmno": {"is_active": True, "power": "128 MW", "code": "PWR2758PL"},
            "Żarnowiec": {"is_active": False, "power": "0 MW", "code": "PWR6132PL"},
        }
    }
).encode("utf-8")


# ─── parse_power_plants ───────────────────────────────────────────────────────


class TestParsePowerPlants:
    def test_returns_one_entry_per_city(self):
        result = parse_power_plants(SAMPLE_LOCATIONS_JSON)
        assert {p.city for p in result} == {"Zabrze", "Chelmno", "Żarnowiec"}

    def test_reads_code(self):
        result = parse_power_plants(SAMPLE_LOCATIONS_JSON)
        chelmno = next(p for p in result if p.city == "Chelmno")
        assert chelmno.code == "PWR2758PL"

    def test_reads_is_active(self):
        result = parse_power_plants(SAMPLE_LOCATIONS_JSON)
        zarnowiec = next(p for p in result if p.city == "Żarnowiec")
        assert zarnowiec.is_active is False


# ─── haversine_km ─────────────────────────────────────────────────────────────


class TestHaversineKm:
    def test_same_point_is_zero(self):
        assert haversine_km(50.0, 18.0, 50.0, 18.0) == pytest.approx(0.0, abs=1e-9)

    def test_known_distance_warsaw_krakow(self):
        # Warszawa (52.2297, 21.0122) → Kraków (50.0647, 19.9450), realnie ~252 km w linii prostej.
        distance = haversine_km(52.2297, 21.0122, 50.0647, 19.9450)
        assert distance == pytest.approx(252, abs=5)

    def test_symmetric(self):
        a = haversine_km(50.3, 18.4, 53.3, 18.4)
        b = haversine_km(53.3, 18.4, 50.3, 18.4)
        assert a == pytest.approx(b)


# ─── find_closest_match ───────────────────────────────────────────────────────


class TestFindClosestMatch:
    def _plants(self):
        return [
            PowerPlant(city="Zabrze", code="PWR3847PL", is_active=True),
            PowerPlant(city="Chelmno", code="PWR2758PL", is_active=True),
        ]

    def _plant_coords(self):
        return {
            "Zabrze": (50.3086, 18.7864),
            "Chelmno": (53.3494, 18.4235),
        }

    def test_picks_globally_closest_pair_not_first_suspect(self):
        """Drugi podejrzany jest bliżej niż pierwszy — musi wygrać drugi, nie pierwszy z brzegu."""
        suspects = [
            {"name": "Daleki", "surname": "Od", "birthYear": 1990},
            {"name": "Bliski", "surname": "Przy", "birthYear": 1991},
        ]
        locations_by_suspect = {
            ("Daleki", "Od"): [{"latitude": 52.0, "longitude": 20.0}],  # daleko od obu
            ("Bliski", "Przy"): [{"latitude": 53.3494, "longitude": 18.4235}],  # dokładnie w Chelmnie
        }

        match = find_closest_match(suspects, locations_by_suspect, self._plants(), self._plant_coords())

        assert (match.name, match.surname) == ("Bliski", "Przy")
        assert match.plant.city == "Chelmno"
        assert match.distance_km == pytest.approx(0.0, abs=0.01)

    def test_checks_every_location_per_suspect(self):
        """Jedna z kilku lokalizacji trafia blisko elektrowni — nie tylko pierwsza z listy."""
        suspects = [{"name": "X", "surname": "Y", "birthYear": 1990}]
        locations_by_suspect = {
            ("X", "Y"): [
                {"latitude": 10.0, "longitude": 10.0},
                {"latitude": 50.3086, "longitude": 18.7864},  # dokładnie w Zabrzu
            ]
        }

        match = find_closest_match(suspects, locations_by_suspect, self._plants(), self._plant_coords())

        assert match.plant.city == "Zabrze"

    def test_raises_on_empty_input(self):
        with pytest.raises(ValueError):
            find_closest_match([], {}, [], {})


# ─── format_answer ────────────────────────────────────────────────────────────


class TestFormatAnswer:
    def test_output_has_required_fields(self):
        match = Match(
            name="Wojciech",
            surname="Bielik",
            birth_year=1986,
            plant=PowerPlant(city="Chelmno", code="PWR2758PL", is_active=True),
            distance_km=0.843,
        )
        result = format_answer(match, access_level=7)
        assert result == {
            "name": "Wojciech",
            "surname": "Bielik",
            "accessLevel": 7,
            "powerPlant": "PWR2758PL",
        }

